using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using UniversityPerformanceApp.Data;
namespace UniversityPerformanceApp.Pages;
public class GradesModel(UniversityPerformanceDb db):PageModel { public List<Grade> Rows{get;private set;}=[];public string? Message{get;private set;} public async Task OnGetAsync()=>Rows=await db.GradesAsync(); private async Task<bool> Valid(int grade){if(grade is >=0 and <=100)return true;Message="Grade must be 0–100.";Rows=await db.GradesAsync();return false;} public async Task<IActionResult> OnPostAddAsync(int studentId,int disciplineId,int grade){if(!await Valid(grade))return Page();await db.ChangeAsync("INSERT dbo.Performance(StudentId,DisciplineId,Grade) VALUES(@studentId,@disciplineId,@grade);",("@studentId",studentId),("@disciplineId",disciplineId),("@grade",grade));return RedirectToPage();} public async Task<IActionResult> OnPostUpdateAsync(int id,int grade){if(!await Valid(grade))return Page();await db.ChangeAsync("UPDATE dbo.Performance SET Grade=@grade WHERE PerformanceId=@id;",("@id",id),("@grade",grade));return RedirectToPage();} public async Task<IActionResult> OnPostDeleteAsync(int id){await db.ChangeAsync("DELETE FROM dbo.Performance WHERE PerformanceId=@id;",("@id",id));return RedirectToPage();}}
